extraCss:
/* Moriarty run hero: portrait source, face sits upper-right */
.hero--bleed{--hero-focus:50% 28%;}
.story-cap{margin-top:9px;font:700 .68rem/1.5 monospace;letter-spacing:.09em;text-transform:uppercase;color:var(--ink-3);}
.art-photo.partner-posed-photo img{aspect-ratio:4/5;object-position:50% 22%;}
.art-photo.crew-track-photo img{aspect-ratio:4/5;object-position:50% 45%;}
.guidance--calm .art-photo.taper-offday-photo img{aspect-ratio:4/5;object-position:50% 30%;}
@media(max-width:600px){.art-photo.partner-posed-photo img{aspect-ratio:4/5;object-position:50% 20%;}.art-photo.crew-track-photo img{aspect-ratio:4/5;object-position:50% 42%;}.guidance--calm .art-photo.taper-offday-photo img{aspect-ratio:4/5;object-position:50% 27%;}}
.capture .bio{object-position:58% 32%;}
.guide-hero-photo img[src*='skierg-laugh.jpg']{object-position:30% 40%!important;}
